def lis(arr):
    dp = [1] * len(arr)
    for i in range(1, len(arr)):
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j]+1)
    return max(dp)

def to_roman(num):
    vals = [(1000,'M'),(900,'CM'),(500,'D'),(400,'CD'),(100,'C'),(90,'XC'),(50,'L'),(40,'XL'),(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')]
    result = ''
    for v, s in vals:
        while num >= v:
            result += s
            num -= v
    return result

def all_paths(graph, start, end):
    def dfs(node, path, result):
        if node == end: result.append(path[:]); return
        for nei in graph.get(node, []):
            if nei not in path:
                path.append(nei)
                dfs(nei, path, result)
                path.pop()
    result = []
    dfs(start, [start], result)
    return result

def missing_number(nums):
    n = len(nums)
    return n*(n+1)//2 - sum(nums)

class Node:
    def __init__(self, val):
        self.val = val; self.prev = self.next = None

class DoublyLinkedList:
    def __init__(self): self.head = None
    def insert(self, val):
        node = Node(val)
        node.next = self.head
        if self.head: self.head.prev = node
        self.head = node

def diameter(root):
    self_max = [0]
    def depth(node):
        if not node: return 0
        l, r = depth(node.left), depth(node.right)
        self_max[0] = max(self_max[0], l+r)
        return 1 + max(l, r)
    depth(root)
    return self_max[0]

def is_balanced(s):
    stack = []
    pairs = {')':'(', ']':'[', '}':'{'}
    for c in s:
        if c in '([{': stack.append(c)
        elif c in ')]}' :
            if not stack or stack[-1] != pairs[c]: return False
            stack.pop()
    return not stack

def lca(root, p, q):
    while root:
        if p.val < root.val and q.val < root.val:
            root = root.left
        elif p.val > root.val and q.val > root.val:
            root = root.right
        else:
            return root

class TrieNode:
    def __init__(self): self.children = {}; self.end = False

class Trie:
    def __init__(self): self.root = TrieNode()
    def insert(self, word):
        node = self.root
        for c in word: node = node.children.setdefault(c, TrieNode())
        node.end = True
    def search(self, word):
        node = self.root
        for c in word:
            if c not in node.children: return False
            node = node.children[c]
        return node.end

def exist(board, word):
    def dfs(r, c, i):
        if i == len(word): return True
        if r<0 or r>=len(board) or c<0 or c>=len(board[0]) or board[r][c]!=word[i]: return False
        tmp, board[r][c] = board[r][c], '#'
        res = any(dfs(r+dr, c+dc, i+1) for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)])
        board[r][c] = tmp
        return res
    return any(dfs(r,c,0) for r in range(len(board)) for c in range(len(board[0])))

import heapq
def merge_k(lists):
    heap = []
    for i, lst in enumerate(lists):
        if lst: heapq.heappush(heap, (lst[0], i, 0))
    result = []
    while heap:
        val, i, j = heapq.heappop(heap)
        result.append(val)
        if j+1 < len(lists[i]): heapq.heappush(heap, (lists[i][j+1], i, j+1))
    return result

def count_distinct_islands(grid):
    seen = set(); shapes = set()
    def dfs(r, c, r0, c0, shape):
        if 0<=r<len(grid) and 0<=c<len(grid[0]) and (r,c) not in seen and grid[r][c]==1:
            seen.add((r,c)); shape.append((r-r0, c-c0))
            for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]: dfs(r+dr, c+dc, r0, c0, shape)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c]==1 and (r,c) not in seen:
                shape=[]; dfs(r,c,r,c,shape); shapes.add(tuple(shape))
    return len(shapes)

from collections import defaultdict
class LFUCache:
    def __init__(self, cap):
        self.cap=cap; self.min_freq=0
        self.key_val={}; self.key_freq={}; self.freq_keys=defaultdict(dict)
    def get(self, key):
        if key not in self.key_val: return -1
        self._inc(key); return self.key_val[key]
    def put(self, key, val):
        if self.cap<=0: return
        if key in self.key_val: self.key_val[key]=val; self._inc(key); return
        if len(self.key_val)==self.cap:
            evict,_=self.freq_keys[self.min_freq].popitem(last=False)
            del self.key_val[evict]; del self.key_freq[evict]
        self.key_val[key]=val; self.key_freq[key]=1
        self.freq_keys[1][key]=1; self.min_freq=1
    def _inc(self, key):
        f=self.key_freq[key]; del self.freq_keys[f][key]
        if f==self.min_freq and not self.freq_keys[f]: self.min_freq+=1
        self.key_freq[key]=f+1; self.freq_keys[f+1][key]=1

def detect_cycle_start(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next; fast = fast.next.next
        if slow == fast:
            slow = head
            while slow != fast: slow = slow.next; fast = fast.next
            return slow
    return None

def max_depth(root):
    if not root: return 0
    return 1 + max(max_depth(root.left), max_depth(root.right))

def serialize(root):
    vals = []
    def dfs(n): vals.append(str(n.val) if n else '#'); dfs(n.left) if n else None; dfs(n.right) if n else None
    dfs(root); return ','.join(vals)
def deserialize(data):
    vals = iter(data.split(','))
    def dfs():
        v = next(vals)
        if v == '#': return None
        node = TreeNode(int(v)); node.left = dfs(); node.right = dfs(); return node
    return dfs()

def coin_change_ways(coins, amount):
    dp = [0] * (amount + 1)
    dp[0] = 1
    for coin in coins:
        for x in range(coin, amount + 1):
            dp[x] += dp[x - coin]
    return dp[amount]

def is_valid_bst(root, lo=float('-inf'), hi=float('inf')):
    if not root: return True
    if root.val <= lo or root.val >= hi: return False
    return is_valid_bst(root.left, lo, root.val) and is_valid_bst(root.right, root.val, hi)

import heapq
def prim(graph, start):
    visited = set([start])
    edges = [(w, start, v) for v, w in graph[start]]
    heapq.heapify(edges)
    mst_cost = 0
    while edges:
        w, u, v = heapq.heappop(edges)
        if v not in visited:
            visited.add(v); mst_cost += w
            for next_v, next_w in graph[v]:
                if next_v not in visited: heapq.heappush(edges, (next_w, v, next_v))
    return mst_cost

import heapq
class MedianFinder:
    def __init__(self): self.lo, self.hi = [], []
    def add(self, num):
        heapq.heappush(self.lo, -num)
        heapq.heappush(self.hi, -heapq.heappop(self.lo))
        if len(self.hi) > len(self.lo): heapq.heappush(self.lo, -heapq.heappop(self.hi))
    def find_median(self):
        if len(self.lo) > len(self.hi): return -self.lo[0]
        return (-self.lo[0] + self.hi[0]) / 2

from itertools import combinations
def combine(n, k):
    return list(combinations(range(1, n+1), k))

class MinStack:
    def __init__(self): self.stack = []; self.min_stack = []
    def push(self, val):
        self.stack.append(val)
        self.min_stack.append(min(val, self.min_stack[-1] if self.min_stack else val))
    def pop(self): self.stack.pop(); self.min_stack.pop()
    def get_min(self): return self.min_stack[-1]

def count_components(n, edges):
    parent = list(range(n))
    def find(x): parent[x] = find(parent[x]) if parent[x]!=x else x; return parent[x]
    def union(x, y): parent[find(x)] = find(y)
    for u, v in edges: union(u, v)
    return len({find(i) for i in range(n)})

def count_palindromes(s):
    count = 0
    for center in range(2*len(s)-1):
        l, r = center//2, (center+1)//2
        while l >= 0 and r < len(s) and s[l] == s[r]:
            count += 1; l -= 1; r += 1
    return count

def dfs(graph, start, visited=None):
    if visited is None: visited = set()
    visited.add(start)
    for neighbor in graph[start]:
        if neighbor not in visited: dfs(graph, neighbor, visited)
    return visited

def unique_paths(m, n):
    dp = [[1]*n for _ in range(m)]
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]
    return dp[m-1][n-1]

def longest_consecutive(nums):
    num_set = set(nums)
    longest = 0
    for n in num_set:
        if n - 1 not in num_set:
            length = 1
            while n + length in num_set: length += 1
            longest = max(longest, length)
    return longest

from collections import deque
def max_width(root):
    if not root: return 0
    max_w = 0
    q = deque([(root, 0)])
    while q:
        _, first = q[0]; _, last = q[-1]
        max_w = max(max_w, last - first + 1)
        next_q = deque()
        for node, idx in q:
            if node.left: next_q.append((node.left, 2*idx))
            if node.right: next_q.append((node.right, 2*idx+1))
        q = next_q
    return max_w
